@staticmethod
def _task_acceptance_requirements(task: str) -> tuple[list[dict[str, str]], list[dict[str, str]]]:
    """Extrahiert explizit strukturierte fachliche Anforderungen und Verifikationen aus dem Auftrag."""
    behavior_texts: list[str] = []
    verification_texts: list[str] = []
    section = ""

    for raw_line in str(task or "").replace("\r\n", "\n").replace("\r", "\n").split("\n"):
        line = raw_line.strip()
        heading = re.match(r"^#{1,6}\s+(.+?)\s*$", line)
        if heading:
            title = " ".join(heading.group(1).lower().split())
            if re.search(r"\b(?:anforderungen?|requirements?)\b", title):
                section = "requirements"
            elif re.search(r"\b(?:verifikation|verification|tests?|prüfung|pruefung)\b", title):
                section = "verification"
            else:
                section = ""
            continue

        bullet = re.match(r"^(?:[-*•]|\d+[.)])\s+(.+)$", line)
        if not bullet:
            continue
        text = re.sub(r"(?:\*\*|__)", "", bullet.group(1)).strip()
        if not text:
            continue

        if section == "verification":
            verification_texts.append(text)
        elif section == "requirements":
            lowered = " ".join(text.lower().split())
            if re.search(
                r"\b(?:muss|müssen|darf|dürfen|soll|sollen|must|should|required|weiterhin)\b",
                lowered,
            ):
                behavior_texts.append(text)

    def unique(items: list[str], prefix: str) -> list[dict[str, str]]:
        result: list[dict[str, str]] = []
        seen: set[str] = set()
        for item in items:
            key = " ".join(item.lower().split())
            if key in seen:
                continue
            seen.add(key)
            result.append({"id": f"{prefix}{len(result) + 1}", "text": item})
        return result

    return unique(behavior_texts, "A"), unique(verification_texts, "V")

@staticmethod
def _verification_requires_behavior(requirement: str) -> bool:
    text = " ".join(str(requirement or "").lower().split())
    return not bool(
        re.search(
            r"\b(?:syntax|lint|kompil|compile|py_compile|format|whitespace|diff[- ]?check)\b",
            text,
        )
    )

@staticmethod
def _validate_acceptance_verifications(
    verifications_raw: Any,
    required_verifications: list[dict[str, str]],
    successful_tests: list[dict[str, str]],
) -> tuple[list[dict[str, Any]], list[str]]:
    """Belegt explizite Verifikationsanforderungen nur durch tatsächlich erfolgreiche Testläufe."""
    if not required_verifications:
        return [], []

    required_by_id = {
        str(item.get("id", "")).strip(): str(item.get("text", "")).strip()
        for item in required_verifications
        if str(item.get("id", "")).strip() and str(item.get("text", "")).strip()
    }
    tests_by_command = {
        str(item.get("command", "")).strip(): str(item.get("output", ""))
        for item in successful_tests
        if str(item.get("command", "")).strip()
    }
    validated: list[dict[str, Any]] = []
    problems: list[str] = []
    seen_ids: set[str] = set()

    if not isinstance(verifications_raw, list):
        verifications_raw = []

    for index, item in enumerate(verifications_raw, 1):
        if not isinstance(item, dict):
            problems.append(f"Verifikation {index} ist kein strukturiertes Objekt.")
            continue
        requirement_id = str(item.get("requirement_id", "")).strip()
        satisfied = item.get("satisfied")
        command = str(item.get("command", "")).strip()
        evidence = str(item.get("evidence", "")).strip()
        reason = str(item.get("reason", "")).strip()

        if requirement_id not in required_by_id:
            problems.append(f"Verifikation {index} verweist auf unbekannte requirement_id {requirement_id or '(leer)'}.")
            continue
        if requirement_id in seen_ids:
            problems.append(f"Verifikation {index} wiederholt requirement_id {requirement_id}.")
            continue
        seen_ids.add(requirement_id)
        requirement = required_by_id[requirement_id]

        if satisfied is not True:
            problems.append(f"{requirement_id}: explizite Verifikationsanforderung ist nicht als erfüllt belegt.")
            continue
        if not command or command not in tests_by_command:
            problems.append(
                f"{requirement_id}: angegebener Prüfcommand wurde im finalen Lauf nicht erfolgreich ausgeführt."
            )
            continue
        if not evidence or not reason:
            problems.append(f"{requirement_id}: command, evidence und reason sind für den Prüfbeleg erforderlich.")
            continue

        combined = command + "\n" + tests_by_command[command]
        canonical_combined = AgentController._canonical_evidence_text(combined)
        canonical_evidence = AgentController._canonical_evidence_text(evidence)
        if not canonical_evidence or canonical_evidence not in canonical_combined:
            problems.append(
                f"{requirement_id}: Prüf-Evidence ist weder im erfolgreichen Befehl noch in dessen Ausgabe vorhanden."
            )
            continue

        required_numbers = AgentController._acceptance_numeric_constraints(requirement)
        missing_numbers = [
            number for number in required_numbers
            if number not in command and number not in evidence and number not in tests_by_command[command]
        ]
        if missing_numbers:
            problems.append(
                f"{requirement_id}: geforderte Grenzwerte fehlen im tatsächlichen Prüfbeleg: "
                + ", ".join(missing_numbers)
            )
            continue

        syntax_only = bool(
            re.search(
                r"(?:\bphp\s+-l\b|\bpython(?:3)?\s+-m\s+py_compile\b|\bnode\s+--check\b|\bgit\s+diff\s+--check\b)",
                command,
                re.I,
            )
        ) and not bool(
            re.search(
                r"(?:\bpytest\b|\bunittest\b|\bphpunit\b|\bassert\b|\bphp\s+-r\b|\bpython(?:3)?\s+-c\b|"
                r"\bnpm\s+(?:run\s+)?test\b|\bpnpm\s+(?:run\s+)?test\b|\byarn\s+test\b|"
                r"\bgo\s+test\b|\bcargo\s+test\b|\bdotnet\s+test\b)",
                command,
                re.I,
            )
        )
        if AgentController._verification_requires_behavior(requirement) and syntax_only:
            problems.append(
                f"{requirement_id}: eine reine Syntax-/Diff-Prüfung belegt die verlangte Verhaltensprüfung nicht."
            )
            continue

        validated.append({
            "requirement_id": requirement_id,
            "requirement": shorten(redact(requirement), 500),
            "satisfied": True,
            "command": shorten(redact(command), 700),
            "evidence": shorten(redact(evidence), 700),
            "reason": shorten(redact(reason), 700),
        })

    valid_ids = {item["requirement_id"] for item in validated}
    for requirement_id, requirement in required_by_id.items():
        if requirement_id in valid_ids:
            continue
        if not any(problem.startswith(requirement_id + ":") for problem in problems):
            problems.append(
                f"{requirement_id}: kein validierter erfolgreicher Prüfbeleg für "
                f"{shorten(redact(requirement), 180)}."
            )
    return validated, problems

@staticmethod
def _validate_acceptance_checks(
    checks_raw: Any,
    final_source: str | dict[str, str],
    required_requirements: list[dict[str, str]] | None = None,
) -> tuple[list[dict[str, str]], list[str]]:
    """Prüft PASS-Belege gegen finalen Dateistand und optional gegen kanonische Auftragsanforderungen."""
    validated: list[dict[str, str]] = []
    problems: list[str] = []
    required_by_id = {
        str(item.get("id", "")).strip(): str(item.get("text", "")).strip()
        for item in (required_requirements or [])
        if str(item.get("id", "")).strip() and str(item.get("text", "")).strip()
    }

    if not isinstance(checks_raw, list) or not checks_raw:
        if required_by_id:
            return [], [
                "Acceptance-PASS enthält keine strukturierten Anforderungsbelege; fehlen: "
                + ", ".join(required_by_id)
            ]
        return [], ["Acceptance-PASS enthält keine strukturierten Anforderungsbelege."]

    seen_requirements: set[str] = set()
    seen_required_ids: set[str] = set()
    for index, item in enumerate(checks_raw, 1):
        if not isinstance(item, dict):
            problems.append(f"Check {index} ist kein strukturiertes Objekt.")
            continue

        requirement_id = str(item.get("requirement_id", "")).strip()
        requirement = str(item.get("requirement", "")).strip()
        satisfied = item.get("satisfied")
        path = str(item.get("path", "")).strip()
        evidence = str(item.get("evidence", "")).strip()
        reason = str(item.get("reason", "")).strip()

        if required_by_id:
            if requirement_id not in required_by_id:
                problems.append(
                    f"Check {index} verweist auf unbekannte requirement_id {requirement_id or '(leer)'}."
                )
                continue
            if requirement_id in seen_required_ids:
                problems.append(f"Check {index} wiederholt requirement_id {requirement_id}.")
                continue
            seen_required_ids.add(requirement_id)
            requirement = required_by_id[requirement_id]

        if not requirement or not path or not evidence or not reason or not isinstance(satisfied, bool):
            problems.append(
                f"Check {index} benötigt requirement, satisfied(bool), path, evidence und reason."
            )
            continue
        if not satisfied:
            problems.append(
                f"Check {index} markiert die Anforderung selbst als nicht vollständig erfüllt: "
                f"{shorten(redact(requirement), 180)}."
            )
            continue
        if AgentController._acceptance_reason_contradicts_satisfied(reason):
            problems.append(
                f"Check {index} ist selbstwidersprüchlich: satisfied=true, aber die Begründung "
                f"nennt eine Lücke (Anforderung: {shorten(redact(requirement), 180)}; "
                f"reason: {shorten(redact(reason), 220)})."
            )
            continue
        required_numbers = AgentController._acceptance_numeric_constraints(requirement)
        missing_numbers = [number for number in required_numbers if number not in evidence]
        if missing_numbers:
            problems.append(
                f"Check {index} belegt konkrete Zahlen/Grenzwerte nicht im Evidence-Ausschnitt: "
                f"{', '.join(missing_numbers)} (Anforderung: {shorten(redact(requirement), 180)})."
            )
            continue
        if len(evidence) < 4:
            problems.append(f"Check {index} enthält einen zu kurzen Beleg.")
            continue

        requirement_key = requirement_id or " ".join(requirement.lower().split())
        if requirement_key in seen_requirements:
            problems.append(f"Check {index} wiederholt dieselbe Anforderung ohne zusätzlichen Nachweis.")
            continue
        seen_requirements.add(requirement_key)

        if isinstance(final_source, dict):
            if path not in final_source:
                problems.append(
                    f"{path}: behaupteter Acceptance-Pfad gehört nicht zum finalen Stand "
                    f"der geänderten Textdateien (Anforderung: {shorten(redact(requirement), 180)})."
                )
                continue
            canonical_current = AgentController._canonical_evidence_text(final_source[path])
            source_label = "finalen Dateistand"
        else:
            if path not in final_source:
                problems.append(
                    f"{path}: behaupteter Acceptance-Pfad kommt im finalen Diff nicht vor "
                    f"(Anforderung: {shorten(redact(requirement), 180)})."
                )
                continue
            current_diff_text = AgentController._acceptance_current_diff_text(final_source)
            canonical_current = AgentController._canonical_evidence_text(current_diff_text)
            source_label = "aktuellen Diff-Inhalt"

        canonical_evidence = AgentController._canonical_evidence_text(evidence)
        if not canonical_evidence or canonical_evidence not in canonical_current:
            problems.append(
                f"{path}: behaupteter Acceptance-Beleg ist im {source_label} nicht vorhanden "
                f"(Anforderung: {shorten(redact(requirement), 180)}; "
                f"Beleg: {shorten(redact(evidence), 180)})."
            )
            continue

        entry = {
            "requirement": shorten(redact(requirement), 500),
            "satisfied": True,
            "path": shorten(redact(path), 300),
            "evidence": shorten(redact(evidence), 700),
            "reason": shorten(redact(reason), 700),
        }
        if requirement_id:
            entry["requirement_id"] = requirement_id
        validated.append(entry)

    if required_by_id:
        valid_ids = {item.get("requirement_id", "") for item in validated}
        for requirement_id, requirement in required_by_id.items():
            if requirement_id in valid_ids:
                continue
            if not any(requirement_id in problem for problem in problems):
                problems.append(
                    f"{requirement_id}: Acceptance-PASS deckt die kanonische Anforderung nicht ab: "
                    f"{shorten(redact(requirement), 180)}."
                )

    return validated, problems
